INSERT INTO `wp_postmeta` VALUES (13465,475,'block_5_text','\"Каталась до 5-го месяца, вышла на лед на 4-й день после родов - как фигуристке удавалось сохранять спокойствие? Эксклюзивное интервью о материнских и спортивных тревогах и важности опоры на человека-скалу.'),(13466,475,'_block_5_text','field_65d3b1a2aaf3s'),(13467,475,'block_5_button_text','Читать'),(13468,475,'_block_5_button_text','field_65d3b1a2aaf4t'),(13469,475,'block_5_button_link','/skolzkij-led-margarita-drobyazko/'),(13470,475,'_block_5_button_link','field_65d3b1a2aaf5u'),(13471,475,'block_5_image','253'),(13472,475,'_block_5_image','field_65d3b1a2aaf6v'),(13473,475,'block_6_title','Ключевые материалы'),(13474,475,'_block_6_title','field_65d3b1a2abg8x'),(13475,475,'block_6_cards','a:3:{i:0;s:3:\"150\";i:1;s:3:\"151\";i:2;s:3:\"152\";}'),(13476,475,'_block_6_cards','field_65d3b1a2abg9y'),(13477,475,'block_6_load_more_text',''),(13478,475,'_block_6_load_more_text','field_65d3b1a2abh0z'),(13479,475,'block_7_card_1_title','Портал \r\n<br>для врачей Синапс'),(13480,475,'_block_7_card_1_title','field_65d3b1a2abi3c'),(13481,475,'block_7_card_1_text','Больше качественной, доступной информации для неврологов и терапевтов '),(13482,475,'_block_7_card_1_text','field_65d3b1a2abi4d'),(13483,475,'block_7_card_1_image','247'),(13484,475,'_block_7_card_1_image','field_65d3b1a2abi5e'),(13485,475,'block_7_card_1_link','https://synapseonline.ru/experts/'),(13486,475,'_block_7_card_1_link','field_65d3b1a2abi6f'),(13487,475,'block_7_card_1',''),(13488,475,'_block_7_card_1','field_65d3b1a2abi2b'),(13489,475,'block_7_card_2_title','Портал территория без тревоги'),(13490,475,'_block_7_card_2_title','field_65d3b1a2abj8h'),(13491,475,'block_7_card_2_text','Помощь врачу и пациенту в диагностике тревожных расстройств '),(13492,475,'_block_7_card_2_text','field_65d3b1a2abj9i'),(13493,475,'block_7_card_2_link','https://xn-----blcffhcbqgai2eitacgzei4z.xn--p1ai/'),(13494,475,'_block_7_card_2_link','field_65d3b1a2abk0j'),(13495,